#!/usr/bin/env python3
"""Destructive fixture: run only inside the disposable QEMU VM wrapper."""
import json
import os
from pathlib import Path
import secrets
import subprocess
import time
import urllib.request


def run(*args, check=True):
    print('VM command:',args,flush=True)
    p = subprocess.run(args, text=True, capture_output=True)
    if check and p.returncode:
        raise RuntimeError(f'{args}: {p.returncode}: {p.stdout} {p.stderr}')
    return p.stdout.strip()


def wait(check):
    end = time.monotonic() + 20
    while time.monotonic() < end:
        try:
            if check(): return
        except (OSError, ValueError): pass
        time.sleep(.1)
    raise RuntimeError('VM operation timed out')


def snapshot():
    rows=[]
    for family in ['-4','-6']:
        for kind in ['rule','route']:
            args=['ip','-j','-N',family,kind,'show']
            if kind=='route': args+=['table','all']
            rows += [kind+family+json.dumps(r,sort_keys=True) for r in json.loads(run(*args))]
    return sorted(rows)


def test():
    assert os.geteuid()==0
    assert os.environ.get('VELUM_DISPOSABLE_VM')=='1'
    assert run('systemd-detect-virt','--vm') in ['kvm','qemu']
    assert Path('/run/velum-f2-disposable').read_text().strip()=='no-host-network'
    assert not any(p.name.startswith(('en','eth')) for p in Path('/sys/class/net').iterdir()), 'VM must have no external NIC'
    run('ip','link','add','f2uplink','type','dummy')
    run('ip','link','set','f2uplink','up')
    for fam, address in [('-4','192.0.2.1/24'),('-6','fd00:2::1/64')]:
        args=['ip',fam,'addr','add',address,'dev','f2uplink']
        if fam=='-6': args+=['nodad']
        run(*args)
        run('ip',fam,'route','add','default','dev','f2uplink')
        run('ip',fam,'rule','add','pref','9000','table','2022')
    for fam,prefix in [('-4','198.51.100.0/24'),('-6','fd00:51::/64')]:
        run('ip',fam,'route','add',prefix,'dev','f2uplink','table','2022')
    baseline=snapshot()
    Path('/etc/velum').mkdir(mode=0o700)
    token=secrets.token_hex(32)
    Path('/etc/velum/token').write_text(token)
    Path('/etc/velum/token').chmod(0o600)
    # Use the actual unit generated by the installer, without running the installer (F15).
    installer=Path('/mnt/velum-f2/install-linux-service.sh').read_text()
    unit=installer.split('cat > "$backup/new-unit" <<EOF\n',1)[1].split('\nEOF',1)[0]
    unit=unit.replace('$xray_arg','').replace('$interface_arg',' --interface f2uplink')
    Path('/etc/systemd/system/velum.service').write_text(unit+'\n')
    run('systemctl','daemon-reload')
    http=urllib.request.build_opener(urllib.request.ProxyHandler({}))
    def api(path,body=None):
        req=urllib.request.Request('http://127.0.0.1:27841/v1/'+path,
            data=None if body is None else json.dumps(body).encode(),
            headers={'Authorization':'Bearer '+token,'Content-Type':'application/json'})
        with http.open(req,timeout=20) as r:return json.load(r)
    def start():
        run('systemctl','start','velum.service')
        wait(lambda: api('status')['state']=='disconnected')
    def connect():
        r=api('connect',{'uri':'vless://00000000-0000-4000-8000-000000000001@192.0.2.2:443?security=reality&sni=example.com&pbk=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA&sid=abcd&flow=xtls-rprx-vision','exclusions':['203.0.113.0/24','fd00:113::/64']})
        assert r['state']=='running',r
    def journal():
        files=list(Path('/run/velum-tun').glob('net-*/journal.json'))
        assert len(files)==1,files
        return files[0]
    def clean():
        assert snapshot()==baseline, 'extra='+str(set(snapshot())-set(baseline))+' missing='+str(set(baseline)-set(snapshot()))
        assert not Path('/sys/class/net/velum0').exists()
        assert not list(Path('/run/velum-tun').glob('net-*/journal.json'))
        assert Path('/run/velum-tun').is_dir(), 'RuntimeDirectory was lost'
    def hooks():
        return run('systemctl','show','velum.service','-p','ExecStartPre','-p','ExecStopPost','-p','RuntimeDirectory','-p','RuntimeDirectoryPreserve','-p','ControlGroup','-p','Result')
    results=[]
    start();connect()
    assert journal().stat().st_mode & 0o777 == 0o600
    assert 'f2uplink' in run('ip','-4','route','get','203.0.113.8','from','192.0.2.1','uid','0')
    assert 'velum0' in run('ip','-4','route','get','203.0.113.8','from','192.0.2.1','uid','1000'), 'Ordinary user source-bind escaped TUN'
    run('systemctl','stop','velum.service');clean()
    print('SYSTEMD HOOKS normal:',hooks(),flush=True)
    results.append('real-unit-normal-stop-and-RuntimeDirectory')
    # Another VPN claims our priorities/table after startup. Exact cleanup preserves it.
    start();connect()
    for fam,prefix in [('-4','203.0.113.0/24'),('-6','fd00:113::/64')]:
        run('ip',fam,'rule','add','pref','27841','table','12022','protocol','250')
        run('ip',fam,'route','add',prefix,'dev','f2uplink','table','27841','proto','250','metric','42')
    run('systemctl','stop','velum.service')
    for fam,prefix in [('-4','203.0.113.0/24'),('-6','fd00:113::/64')]:
        assert any(r.get('priority')==27841 and str(r.get('table'))=='12022' for r in json.loads(run('ip','-j','-N',fam,'rule','show')))
        assert any(r.get('dst')==prefix and r.get('metric')==42 for r in json.loads(run('ip','-j','-N',fam,'route','show','table','27841')))
        run('ip',fam,'rule','del','pref','27841','table','12022','protocol','250')
        run('ip',fam,'route','del',prefix,'dev','f2uplink','table','27841','proto','250','metric','42')
    clean();results.append('foreign-same-priority-and-table-dual-stack')
    # Prove StopPost independently: no new main process may help recovery.
    dropin=Path('/run/systemd/system/velum.service.d/f2-test.conf')
    dropin.parent.mkdir(parents=True, exist_ok=True)
    dropin.write_text('[Service]\nRestart=no\n')
    run('systemctl','daemon-reload');start();connect()
    run('systemctl','kill','--kill-whom=all','--signal=SIGSTOP','velum.service')
    run('systemctl','kill','--kill-whom=all','--signal=SIGKILL','velum.service')
    wait(lambda: run('systemctl','is-active','velum.service',check=False)=='failed')
    clean()
    post=run('systemctl','show','velum.service','-p','ExecStopPost','--value')
    assert 'code=exited' in post and 'status=0' in post and 'pid=0 ' not in post, post
    print('SYSTEMD StopPost without restart:',post,flush=True)
    results.append('ExecStopPost-alone-after-cgroup-SIGKILL')
    dropin.unlink();run('systemctl','daemon-reload')
    # Stop every process first; then kill the cgroup. No Go defer can run.
    start();connect()
    print('VM cgroup before kill:', run('systemctl','show','velum.service','-p','ControlGroup','-p','MainPID'), 'test pid:',os.getpid(), Path('/proc/self/cgroup').read_text(), flush=True)
    invocation=run('systemctl','show','velum.service','-p','InvocationID','--value')
    run('systemctl','kill','--kill-whom=all','--signal=SIGSTOP','velum.service')
    run('systemctl','kill','--kill-whom=all','--signal=SIGKILL','velum.service')
    wait(lambda: run('systemctl','show','velum.service','-p','InvocationID','--value')!=invocation and run('systemctl','is-active','velum.service',check=False)=='active')
    wait(lambda: api('status')['state']=='disconnected');clean()
    print('SYSTEMD HOOKS killed cgroup:',hooks(),flush=True)
    connect();run('systemctl','stop','velum.service');clean()
    results.append('SIGKILL-cgroup-ExecStopPost-auto-restart')
    # Isolate ExecStartPre: deliberately suppress StopPost for this one crash.
    dropin=Path('/run/systemd/system/velum.service.d/f2-test.conf')
    dropin.parent.mkdir(parents=True, exist_ok=True)
    dropin.write_text('[Service]\nExecStopPost=\nRestart=no\n')
    run('systemctl','daemon-reload');start();connect()
    run('systemctl','kill','--kill-whom=all','--signal=SIGSTOP','velum.service')
    run('systemctl','kill','--kill-whom=all','--signal=SIGKILL','velum.service')
    wait(lambda: run('systemctl','is-active','velum.service',check=False)=='failed')
    stale=journal();saved=stale.read_bytes()
    assert snapshot()!=baseline and not Path('/sys/class/net/velum0').exists()
    # A corrupt journal must block ExecStartPre without network mutation.
    before=snapshot();stale.write_bytes(b'{broken')
    dropin.unlink();run('systemctl','daemon-reload')
    failed=subprocess.run(['systemctl','start','velum.service'],capture_output=True,text=True)
    assert failed.returncode!=0,'Corrupt recovery was accepted'
    assert snapshot()==before and stale.read_bytes()==b'{broken'
    run('systemctl','stop','velum.service') # cancel Restart=on-failure for deterministic repair
    stale.write_bytes(saved);stale.chmod(0o600)
    # A second Pre command asserts the production Pre cleaned before main's
    # own startup recovery can run and accidentally mask a broken unit hook.
    guard=Path('/usr/local/lib/velum/f2-pre-check')
    guard.write_text('#!/bin/sh\nexec /bin/test ! -e '+str(stale)+'\n')
    guard.chmod(0o755)
    dropin.write_text('[Service]\nExecStartPre=/usr/local/lib/velum/f2-pre-check\n')
    run('systemctl','daemon-reload')
    start();clean()
    dropin.unlink();run('systemctl','daemon-reload')
    print('SYSTEMD HOOKS recovered StartPre:',hooks(),flush=True)
    results.extend(['SIGKILL-journal-preserved-without-StopPost','corrupt-journal-safe-refusal','ExecStartPre-stale-recovery'])
    for _ in range(3):
        connect();assert api('disconnect',{})['state']=='disconnected';clean()
    run('systemctl','stop','velum.service');clean()
    results.append('repeated-connect-disconnect-after-recovery')
    run('systemctl','disable','velum.service',check=False)
    Path('/etc/systemd/system/velum.service').unlink()
    run('systemctl','daemon-reload')
    return {'passed':results,'systemd':run('systemctl','--version').splitlines()[0],
            'kernel':run('uname','-r'),'os':Path('/etc/os-release').read_text()}


if __name__=='__main__':
    try:
        result=test()
        print('VELUM_SYSTEMD_RESULT:'+json.dumps({'success':True,**result}),flush=True)
    except BaseException as e:
        print(run('journalctl','-u','velum.service','--no-pager','-n','100',check=False),flush=True)
        print('VELUM_SYSTEMD_RESULT:'+json.dumps({'success':False,'error':repr(e)}),flush=True)
        raise
